1: <!--
2: 	ALE-381: the person's Intake page. Everything shown is Phoenix's safe
3: 	view; the one action is Phoenix's too. Pay mounts embedded Checkout;
4: 	"Check again" and the
5: 	payment-in-progress refresh reload Phoenix's view. A Carried Fee holder
6: 	(ALE-388) gets "Confirm my place" instead of Pay. No self-service
7: 	decline or withdraw: replies to the email go through a coordinator.
8: -->
9: <script lang="ts">
10: import { tick } from "svelte";
11: import type { BeginnersIntakePage } from "@dhc/api-client";
12: import { CalendarDays, Clock, MapPin, RefreshCw } from "@lucide/svelte";
