16: import {
17: 	confirmsWithCarriedFee,
18: 	intakeActionLabel,
19: 	intakeCopy,
20: 	intakeDetails,
21: 	REFRESH_MS,
22: 	startsCheckout,
23: } from "#lib/beginners-workshops/intake-page.js";
24: import * as Alert from "#lib/components/ui/alert/index.js";
25: import { Badge } from "#lib/components/ui/badge/index.js";
26: import { Button } from "#lib/components/ui/button/index.js";
27: import * as Card from "#lib/components/ui/card/index.js";
28: import { confirmIntakePlace, startIntakePayment } from "./intake.remote";
29: 
30: let {
31: 	page,
32: 	token,
33: 	refresh = () => void invalidateAll(),
34: 	refreshMs = REFRESH_MS,
35: 	startPayment = () => paymentForm.submit(),
36: }: {
37: 	page: BeginnersIntakePage;
38: 	token: string;
39: 	refresh?: () => void;
40: 	refreshMs?: number;
41: 	startPayment?: () => Promise<boolean>;
42: } = $props();
43: 
44: const formId = $props.id();
45: const paymentForm = startIntakePayment.for(formId);
46: const confirmForm = confirmIntakePlace.for(formId);
47: const copy = $derived(intakeCopy(page));
48: const details = $derived(intakeDetails(page));
49: const actionLabel = $derived(intakeActionLabel(page));
50: const checkout = $derived(startsCheckout(page));
51: const confirms = $derived(confirmsWithCarriedFee(page));
52: const payment = $derived(paymentForm.result?.ok ? paymentForm.result : null);
53: let requestFailed = $state(false);
54: const refusal = $derived.by(() => {
55: 	const result = confirms ? confirmForm.result : paymentForm.result;
56: 	if (result?.ok) return null;
57: 	return result && !result.ok
58: 		? result.error
59: 		: requestFailed
60: 			? "Payment is unavailable right now. Please try again shortly."
61: 			: null;
62: });
63: 
64: // Opening the email link opens payment too. POST still takes the Seat Hold;
65: // the page's GET never reserves a place. A live hold resumes the same session.
66: let initiated = false;
67: $effect(() => {
68: 	if (!checkout || initiated) return;
69: 	initiated = true;
70: 	void openPayment();
71: });
72: 
73: async function openPayment() {
74: 	await tick(); // The remote form must be attached before programmatic submit.
75: 	try {
76: 		await startPayment();
77: 	} catch {
78: 		requestFailed = true;
79: 	}
80: }
81: 
82: // `payment_in_progress` asks Phoenix again until it reports `paid`.
83: $effect(() => {
84: 	if (page.state !== "payment_in_progress") return;
85: 	const timer = setTimeout(() => refresh(), refreshMs);
86: 	return () => clearTimeout(timer);
87: });
88: </script>
