118: 					>
119: 				</p>
120: 			{/if}
121: 			{#if refusal}
122: 				<Alert.Root variant="destructive">
123: 					<Alert.Description>{refusal}</Alert.Description>
124: 				</Alert.Root>
125: 			{/if}
126: 		</Card.Content>
127: 	{/if}
128: 
129: 	{#if actionLabel}
