131: 			<Card.Content>
132: 				<p class="text-sm text-muted-foreground">
133: 					Payment deadline: {formatDublinInstant(page.paymentCutoff)}
134: 				</p>
135: 			</Card.Content>
136: 		{/if}
137: 		<Card.Footer>
138: 			{#if checkout && payment}
139: 				{#key payment.clientSecret}
140: 					<IntakeCheckout
141: 						clientSecret=REDACTED
142: 						onComplete={() =>
143: 							goto(`?session_id=${encodeURIComponent(payment.sessionId)}`)}
144: 					/>
145: 				{/key}
146: 			{:else if checkout}
147: 				{#if !refusal}
148: 					<p role="status" class="py-4 text-sm text-muted-foreground">
149: 						Loading secure payment…
150: 					</p>
151: 				{/if}
152: 				<form {...paymentForm} class="w-full" hidden={!refusal}>
153: 					<input {...paymentForm.fields.token.as("hidden", token)} />
154: 					<Button
155: 						type="submit"
156: 						class="w-full"
157: 						disabled={!!paymentForm.pending}
158: 						aria-busy={!!paymentForm.pending}
159: 					>
160: 						{paymentForm.pending ? "Loading secure payment…" : "Try again"}
161: 					</Button>
162: 				</form>
163: 			{:else if confirms}
164: 				<form {...confirmForm} class="w-full">
165: 					<input {...confirmForm.fields.token.as("hidden", token)} />
166: 					<Button type="submit" class="w-full" disabled={!!confirmForm.pending}>
167: 						{actionLabel}
168: 					</Button>
169: 				</form>
170: 			{:else}
171: 				<Button
172: 					variant="outline"
173: 					class="w-full"
174: 					onclick={() => refresh()}
175: 					aria-busy={page.state === "payment_in_progress"}
176: 				>
177: 					<RefreshCw
178: 						class={page.state === "payment_in_progress" ? "animate-spin" : ""}
179: 					/>
180: 					{actionLabel}
181: 				</Button>
182: 			{/if}
183: 		</Card.Footer>
184: 	{/if}
185: </Card.Root>

