5:  * credential, so the page never sends a referrer and is never cached.
6:  */
7: import { error } from "@sveltejs/kit";
8: import {
9: 	beginnersWorkshopIntakeReturnFromCheckout,
10: 	beginnersWorkshopIntakeShow,
11: 	type BeginnersIntakePage,
12: } from "@dhc/api-client";
13: import { INACTIVE_PAGE } from "#lib/beginners-workshops/intake-page.js";
14: import { apiClientOptions } from "#lib/server/api-client.js";
15: import type { PageServerLoad } from "./$types";
16: 
17: export const load: PageServerLoad = async ({
18: 	params,
19: 	url,
20: 	cookies,
21: 	setHeaders,
22: }) => {
23: 	setHeaders({ "referrer-policy": "no-referrer", "cache-control": "no-store" });
24: 
25: 	const options = {
26: 		...apiClientOptions(cookies),
27: 		path: { token: params.token },
28: 	};
29: 	const sessionId = url.searchParams.get("session_id");
30: 
31: 	const response = sessionId
32: 		? await beginnersWorkshopIntakeReturnFromCheckout({
33: 				...options,
34: 				body: { sessionId },
35: 			})
36: 		: await beginnersWorkshopIntakeShow(options);
37: 
38: 	if (response.data) return { page: response.data.data, token: params.token };
39: 	if (response.response?.status === 404) {
40: 		return {
41: 			page: INACTIVE_PAGE satisfies BeginnersIntakePage,
42: 			token: params.token,
43: 		};
44: 	}
45: 
46: 	error(
47: 		503,
48: 		"We couldn't load your place right now. Please try again shortly.",
49: 	);
50: };

