Read file apps/web/src/lib/destinations.ts, lines 1-50
1: /**
2:  * Attendee-facing destination presentation (ALE-440).
3:  *
4:  * Pure helpers over the destination facts every workshop read carries. A
5:  * manually supplied link was already validated by Phoenix as a supported
6:  * HTTPS Maps destination; when there is none, the saved name/address facts
7:  * build an ordinary Maps search. Legacy rows have no facts and keep their
8:  * short venue label only — nothing here fabricates a place for unreviewed
9:  * text.
10:  */
11: 
12: /** The destination facts a workshop read carries (all optional/nullable). */
13: export interface DestinationFacts {
14: 	destinationName?: string | null;
15: 	destinationAddress?: string | null;
16: 	directionsUrl?: string | null;
17: }
18: 
19: const trimmed = (value: string | null | undefined) =>
20: 	value?.trim() ? value.trim() : undefined;
21: 
22: /**
23:  * The recognizable destination detail lines to show beside the familiar
24:  * venue label: the name, then the address. Empty when the row has no
25:  * destination details.
26:  */
27: export function destinationLines(workshop: DestinationFacts): string[] {
28: 	return [
29: 		trimmed(workshop.destinationName),
30: 		trimmed(workshop.destinationAddress),
31: 	].filter((line): line is string => line !== undefined);
32: }
33: 
34: /**
35:  * The external directions link for an attendee, or `undefined` when there is
36:  * nothing useful to link to.
37:  *
38:  * The manually supplied Maps link wins; otherwise the destination name and
39:  * address build a Maps search. A directions link alone (no name/address) is
40:  * still a usable destination.
41:  */
42: export function directionsHref(workshop: DestinationFacts): string | undefined {
43: 	const manual = trimmed(workshop.directionsUrl);
44: 	if (manual) return manual;
45: 
46: 	const query = destinationLines(workshop).join(", ");
47: 	if (!query) return undefined;
48: 
49: 	return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
50: }

