33:  * (until ALE-163), but the dashboard no longer sends one — the cookie is the
34:  * only credential.
35:  */
36: export function apiClientOptions(
37: 	cookies: Cookies,
38: 	forwarding: ClientForwarding = currentRequestForwarding(),
39: ) {
40: 	const sessionCookie = cookies.get("_dhc_session");
41: 	const headers: Record<string, string> = {};
42: 	if (sessionCookie) {
43: 		headers.cookie = `_dhc_session=${sessionCookie}`;
44: 	}
