63:  * Where the browser's address comes from: the shared secret and the current
64:  * request's client address (`undefined` outside a request).
65:  */
66: export interface ClientForwarding {
67: 	secret: string | undefined;
68: 	clientAddress(): string | undefined;
69: }
70: 
71: function currentRequestForwarding(): ClientForwarding {
72: 	return {
73: 		secret: TRUSTED_FORWARDING_SECRET,
74: 		clientAddress() {
